content.content:
#include <stdio.h>

int main() {
    float purchases[3] = {10.99, 14.25, 90.50};
    float total = 0;
    int k;

    /* 遍历purchases，并累加 */
    for (k = 0; k < 3; k++) {
        total += purchases[k];
    }

    printf("Purchases total is %6.2f\n", total);
    /* Output:  Purchases total is 115.74 */ 

	return 0;
}

#include <stdio.h>

int main() {
    int a[10];
    int k;

    for (k = 0; k < 10; k++) {
        a[k] = k * 10;
    } 

    for (k = 0; k < 10; k++) {
        printf("%d \n", a[k]);
    }

	return 0;
}

